/bin/zsh -c "python3 -c \"import pandas as pd, json, os; b='evidence/raw'; fs=['orders-part1.csv','orders-part2.csv','order-corrections.csv','returns.csv','hub-options.csv','unit-costs.csv'];
for f in fs:
 d=pd.read_csv(os.path.join(b,f)); print('\\\\n'+f,d.shape); print(d.head(2).to_string(index=False));
 for c in ['status','is_test','country','currency','revision','received_at','shipped_at']:
  if c in d: print(c, d[c].value_counts(dropna=False).head(20).to_dict() if c not in ['received_at','shipped_at'] else (d[c].astype(str).min(),d[c].astype(str).max()))
 print('dupe rows',d.duplicated().sum(),'first-col dupes',d.iloc[:,0].duplicated().sum())
for f in ['population.json','gdp-per-capita.json']:
 print(f,json.load(open(os.path.join(b,f)))[0])\""

